if (STL_SCH_InitRam(&StlRamStatus) != STL_OK)

{

Thread_FailSafe_Handler(TMR_ERR_CODE + DEF_PROG_OFFSET);

}

if (STL_SCH_ConfigureRam(&StlRamStatus, &MyRamConfigRunTime) != STL_OK)

{

Thread_FailSafe_Handler(TMR_ERR_CODE + DEF_PROG_OFFSET);

